import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_pdf_editor/flutter_pdf_editor.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:pdf_engine_core/pdf_engine_core.dart';

/// Shared corpus generated by tool/generate_fixtures.py.
Uint8List _fixture(String name) =>
    File('../fixtures/pdf/$name').readAsBytesSync();

Matcher _unsupported(PdfUnsupportedFeature feature) => throwsA(
  isA<PdfUnsupportedFeatureException>().having(
    (error) => error.feature,
    'feature',
    feature,
  ),
);

Matcher _editableRejected(PdfUnsupportedFeature feature) => throwsA(
  isA<PdfEditableExportException>().having(
    (error) => error.cause,
    'cause',
    isA<PdfUnsupportedFeatureException>().having(
      (cause) => cause.feature,
      'feature',
      feature,
    ),
  ),
);

PdfTextFormField _textField(List<PdfFormField> fields, String name) =>
    fields.whereType<PdfTextFormField>().firstWhere((f) => f.name == name);

void main() {
  final parser = PdfAcroFormParser();

  group('AcroForm parser on the fixture corpus', () {
    test('reads every field type from form_classic.pdf', () {
      final fields = parser.parseBytes(_fixture('form_classic.pdf'));
      expect(
        fields.map((field) => field.name),
        containsAll(<String>[
          'full_name',
          'email',
          'accept_terms',
          'country',
          'skills',
        ]),
      );
      expect(fields.whereType<PdfTextFormField>(), hasLength(2));
      expect(fields.whereType<PdfCheckboxFormField>(), hasLength(1));
      expect(fields.whereType<PdfRadioFormField>(), hasLength(2));
    });

    test('reads values written by another tool (form_filled.pdf)', () {
      final fields = parser.parseBytes(_fixture('form_filled.pdf'));
      expect(_textField(fields, 'full_name').value, 'Sakibul Haque');
    });

    test('uses the latest revision of an incrementally updated form', () {
      final fields = parser.parseBytes(_fixture('form_incremental_update.pdf'));
      expect(_textField(fields, 'full_name').value, 'Incremental Value');
    });

    test('inherits the field type from a parent field', () {
      final fields = parser.parseBytes(_fixture('form_hierarchical_names.pdf'));
      expect(
        fields.whereType<PdfTextFormField>().map((field) => field.name),
        unorderedEquals(<String>['name', 'email']),
      );
    });

    test('returns no fields for a PDF without a form', () {
      expect(parser.parseBytes(_fixture('text_single_page.pdf')), isEmpty);
      expect(parser.parseBytes(_fixture('flate_content_stream.pdf')), isEmpty);
    });

    test('reads forms stored in compressed object streams', () {
      final classic = parser.parseBytes(_fixture('form_classic.pdf'));
      final compressed = parser.parseBytes(_fixture('form_object_streams.pdf'));
      expect(
        compressed.map((field) => '${field.runtimeType}:${field.name}'),
        classic.map((field) => '${field.runtimeType}:${field.name}'),
      );
    });

    test('reads forms whose newest revision uses an xref stream', () {
      final fields = parser.parseBytes(
        _fixture('form_incremental_xref_stream.pdf'),
      );
      expect(_textField(fields, 'full_name').value, 'Incremental Value');
    });

    test('rejects encrypted forms with a typed exception', () {
      expect(
        () => parser.parseBytes(_fixture('form_encrypted.pdf')),
        _unsupported(PdfUnsupportedFeature.encryption),
      );
    });

    test('rejects XFA-only forms with a typed exception', () {
      expect(
        () => parser.parseBytes(_fixture('form_xfa_only.pdf')),
        _unsupported(PdfUnsupportedFeature.xfaForms),
      );
    });

    test('rejects non-PDF data', () {
      expect(
        () => parser.parseBytes(_fixture('not_a_pdf.pdf')),
        throwsA(isA<PdfInvalidDocumentException>()),
      );
    });

    test('reports a missing file with PdfFileNotFoundException', () {
      expect(
        parser.parse(
          const PdfDocumentSource.file('../fixtures/pdf/missing.pdf'),
        ),
        throwsA(isA<PdfFileNotFoundException>()),
      );
    });
  });

  group('Editable exporter on the fixture corpus', () {
    final exporter = PdfEditableExporter();

    Future<void> expectRoundTrip(String fixture) async {
      final bytes = _fixture(fixture);
      final fields = parser.parseBytes(bytes);
      final edited = _textField(
        fields,
        'full_name',
      ).copyWith(value: 'Round Trip');

      final output = await exporter.exportToBytes(
        source: PdfDocumentSource.bytes(bytes),
        formFields: <PdfFormField>[edited],
      );

      expect(output.length, greaterThan(bytes.length));
      expect(PdfPreflight.inspect(output).revisionCount, greaterThan(1));
      final reparsed = parser.parseBytes(output);
      expect(_textField(reparsed, 'full_name').value, 'Round Trip');
      expect(reparsed.length, fields.length);
    }

    test('saves form_classic.pdf as an incremental update', () {
      return expectRoundTrip('form_classic.pdf');
    });

    test('saves on top of an existing incremental update', () {
      return expectRoundTrip('form_incremental_update.pdf');
    });

    test(
      'keeps newlines, parentheses and backslashes through a save',
      () async {
        const value = 'Line one\nLine (two) \\ end';
        final bytes = _fixture('form_classic.pdf');
        final field = _textField(
          parser.parseBytes(bytes),
          'full_name',
        ).copyWith(value: value);
        final output = await exporter.exportToBytes(
          source: PdfDocumentSource.bytes(bytes),
          formFields: <PdfFormField>[field],
        );
        expect(_textField(parser.parseBytes(output), 'full_name').value, value);
      },
    );

    test('saves forms stored in compressed object streams', () {
      return expectRoundTrip('form_object_streams.pdf');
    });

    test('saves on top of a cross-reference stream update', () {
      return expectRoundTrip('form_incremental_xref_stream.pdf');
    });

    test('rejects encrypted files', () {
      expect(
        exporter.exportToBytes(
          source: PdfDocumentSource.bytes(_fixture('form_encrypted.pdf')),
          formFields: const <PdfFormField>[],
        ),
        _editableRejected(PdfUnsupportedFeature.encryption),
      );
    });

    test('every editor exception is a PdfException', () {
      expect(const PdfEditableExportException('x'), isA<PdfException>());
      expect(const PdfExportCancelledException(), isA<PdfException>());
      expect(const PdfExportValidationException('x'), isA<PdfException>());
    });
  });
}
